WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.Score, p.ViewCount, p.OwnerUserId, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS RN FROM Posts AS p WHERE p.CreationDate >= CAST('2024-10-01' AS Nullable(DATE)) - INTERVAL '1' YEAR), UserReputation AS (SELECT u.Id AS UserId, SUM(u.Reputation) AS TotalReputation FROM Users AS u JOIN Posts AS p ON u.Id = p.OwnerUserId GROUP BY u.Id), VotesSummary AS (SELECT v.PostId, COUNT(CASE WHEN v.VoteTypeId = 2 THEN 1 END) AS UpVotes, COUNT(CASE WHEN v.VoteTypeId = 3 THEN 1 END) AS DownVotes FROM Votes AS v GROUP BY v.PostId), PostHistoryDetails AS (SELECT ph.PostId, GROUP_CONCAT(ph.Comment, ', ') AS EditComments FROM PostHistory AS ph WHERE ph.PostHistoryTypeId IN (4, 5, 6) GROUP BY ph.PostId) SELECT rp.PostId, rp.Title, rp.CreationDate, COALESCE(vs.UpVotes, 0) AS UpVotes, COALESCE(vs.DownVotes, 0) AS DownVotes, COALESCE(u.TotalReputation, 0) AS TotalUserReputation, COALESCE(phd.EditComments, 'No edits recorded') AS EditComments FROM RankedPosts AS rp LEFT JOIN VotesSummary AS vs ON rp.PostId = vs.PostId LEFT JOIN UserReputation AS u ON rp.OwnerUserId = u.UserId LEFT JOIN PostHistoryDetails AS phd ON rp.PostId = phd.PostId WHERE rp.RN = 1 ORDER BY rp.CreationDate DESC NULLS FIRST LIMIT 100